@Configuration
@Endpoint(id = "caches")
public class CustomCacheManagementEndpoint {

    private final CacheManager cacheManager;

    public CustomCacheManagementEndpoint(CacheManager cacheManager) {
        this.cacheManager = cacheManager;
    }

    @ReadOperation
    public Map<String, Object> cacheStatistics() {
        Map<String, Object> stats = new HashMap<>();
        for (String cacheName : cacheManager.getCacheNames()) {
            stats.put(cacheName, "Active entries: " + ((ConcurrentMapCache) cacheManager.getCache(cacheName)).getNativeCache().size());
        }
        return stats;
    }

    @WriteOperation
    public void evictCache(@Selector String cacheName) {
        var cache = cacheManager.getCache(cacheName);
        if (cache != null) {
            cache.clear();
        }
    }
}
